draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw glass
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-100, 100, 150);
  ctx.stroke();

  // Draw milk alternative
  ctx.fillStyle = '#ccccff';
  ctx.fillRect(W/2-45, H/2-95, 90, 140);

  // Draw calcium symbol
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Ca', W/2, H/2-50);

  // Draw bone
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2+50, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2-20, H/2+80, 40, 10);
  ctx.stroke();

  // Animate calcium symbol and bone
  ctx.save();
  ctx.translate(W/2, H/2-50);
  ctx.rotate(Math.sin(t));
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Ca', 0, 0);
  ctx.restore();

  ctx.save();
  ctx.translate(W/2, H/2+50);
  ctx.rotate(Math.sin(t+Math.PI/2));
  ctx.beginPath();
  ctx.arc(0, 0, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(-20, 30, 40, 10);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
